def optimize_renderprep(override, game):
    state = (game / 'Source/Graphics/RenderState.cs').read_text()
    tail = state[state.index('\t\tmat.NearPlane'):state.rindex('\n\t}')]
    override('Graphics/RenderState.cs', [('public void ApplyToMaterial(DefaultMaterial mat, in Matrix localTransformation)', '// One instance per model/drawable and render pass. Never shared between\n    // passes, cameras or moving models; material setter order is unchanged.\n    public struct MaterialMatrices\n    {\n        internal bool Ready;\n        internal Matrix Model, MVP;\n    }\n\n    public void ApplyToMaterial(DefaultMaterial mat, in Matrix localTransformation, ref MaterialMatrices matrices)\n    {\n        if (mat.Shader == null) return;\n        if (!matrices.Ready)\n        {\n            matrices.Model = localTransformation * ModelMatrix;\n            matrices.MVP = matrices.Model * Camera.ViewProjection;\n            matrices.Ready = true;\n        }\n        mat.Model = matrices.Model;\n        mat.MVP = matrices.MVP;\n' + tail + '\n    }\n\n    public void ApplyToMaterial(DefaultMaterial mat, in Matrix localTransformation)')])
    override('Graphics/SimpleModel.cs', [('public override void Render(ref RenderState state)\n\t{', 'public override void Render(ref RenderState state)\n\t{\n        RenderState.MaterialMatrices matrices = default;'), ('state.ApplyToMaterial(mat, Matrix.Identity);', 'state.ApplyToMaterial(mat, Matrix.Identity, ref matrices);')])
    override('Graphics/SkinnedModel.cs', [('var meshPart = Template.Parts[drawable.Template.LogicalMeshIndex];', 'var meshPart = Template.Parts[drawable.Template.LogicalMeshIndex];\n            RenderState.MaterialMatrices matrices = default;'), ('state.ApplyToMaterial(mat, statXform.WorldMatrix * BaseTranslation);', 'state.ApplyToMaterial(mat, statXform.WorldMatrix * BaseTranslation, ref matrices);'), ('state.ApplyToMaterial(mat, BaseTranslation);', 'state.ApplyToMaterial(mat, BaseTranslation, ref matrices);')])
